head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16403";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — count, disableYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16403.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_45_txt", fn: function(){ return ((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '1'); } }, { id: "c_when_46_txt", fn: function(){ return ((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '2'); } }, { id: "c_otherwise_47", fn: function(){ return (!(((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '1') || ((dma_educationList.get("roomTpCd") ?? (() => { throw new Error("unresolved:" + "educationList.roomTpCd"); })()) === '2'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb1", fn: function () { return String((String(String(dma_eduDisclsChrg.get("bzRegNo")) == null ? '' : String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,'').length === 10 ? String(dma_eduDisclsChrg.get("bzRegNo")).replace(/[^0-9]/g,'').slice(0,3) + '-' + String(dma_eduDisclsChrg.get("bzRegNo")).replace(/[^0-9]/g,'').slice(3,5) + '-' + String(dma_eduDisclsChrg.get("bzRegNo")).replace(/[^0-9]/g,'').slice(5) : String(String(dma_eduDisclsChrg.get("bzRegNo")) == null ? '' : String(dma_eduDisclsChrg.get("bzRegNo"))).replace(/[^0-9]/g,''))); } },
        { childId: "__rb3", fn: function () { return String(dma_educationList.get("eduPartcCnt")) + " 명"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_history_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_history_onclick = function(e){
    try {
        history.back()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16403.btn_history_onclick' }); }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function(e){
    try {
        await scwin.deleteRegisterReq('' + dma_educationList.get("disclsEduApplSeq") + '','' + dma_educationList.get("submitYn") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16403.btn_Delete_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: action ?? "/support/eduRspn.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: action ?? "/support/eduRspn.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: action ?? "/support/eduRspn.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (_submitYn) {
    if (!await scwin.chk2()) {
        return;
    }
    if ($c.util.getComponent('dma_RegisterReq').get('disclsEduApplSeq') === '69') {
        let count = (String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))));
        if (parseInt(count) >= 150) {
            await $c.win.alert("교육수용인원이 초과되어 접수를 마감하였습니다.\n다음차수에 신청하여 주시기 바랍니다. 감사합니다.");
            return;
        }
    }
    if ($c.util.getComponent('dma_RegisterReq').get('disclsEduApplSeq') === '70') {
        count = (String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("count") ?? "")) == null ? '' : ((dma_pageContext.get("count") ?? ""))));
        if (parseInt(count) >= 140) {
            await $c.win.alert("교육수용인원이 초과되어 접수를 마감하였습니다.\n다음차수에 신청하여 주시기 바랍니다. 감사합니다.");
            return;
        }
    }
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerResponsibilityEducation');
    await scwin.tx_fn_Register('eduRspn.do');
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_submitYn) {
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'modifyResponsibilityEducation');
    await scwin.tx_fn_Modify('eduRspn.do');
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @param {*} _disclsEduApplSeq _disclsEduApplSeq
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _submitYn) {
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        $c.util.getComponent('dma_RegisterReq').set('disclsEduApplSeq', _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeResponsibilityEducation');
        await scwin.tx_fn_Delete('eduRspn.do');
    } else {
        return;
    }
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.reset = function () {
    const frm = (document.eduForm || { elements: [] });
    frm.reset();
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {void}
 * @hidden N
 */
scwin.print = async function () {
    await $c.win.print();
};

/**
 * @method
 * @name chk2
 * @description chk2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk2 = async function () {
    const frm = (document.eduForm || { elements: [] });
    if ((String(((dma_pageContext.get("disableYn") ?? "")) == null ? '' : ((dma_pageContext.get("disableYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("disableYn") ?? "")) == null ? '' : ((dma_pageContext.get("disableYn") ?? "")))) === 'Y') {
        if (frm.roomTpCd.value === "") {
            await $c.win.alert("간담회 참석여부를 선택해주세요.");
            roomTpCd.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk = async function () {
    const frm = (document.eduForm || { elements: [] });
    if (frm.depAirtkClssCd.value !== "") {
        if (frm.depTpCd.value !== "01" || frm.depIndvdlMvYn.value !== "N") {
            await $c.win.alert("서울&단체 이동인 경우에만 선택 가능합니다");
            depAirtkClssCd.focus();
            return false;
        }
    }
    if (frm.depReservprnTpCd.value !== "") {
        if (frm.depTpCd.value === "01") {
            await $c.win.alert("지방 출발시만  선택 가능합니다");
            depReservprnTpCd.focus();
            return false;
        }
    }
    if (frm.destAirtkClssCd.value !== "") {
        if (frm.destTpCd.value !== "01" || frm.destIndvdlMvYn.value !== "N") {
            await $c.win.alert("서울&단체 이동인 경우에만 선택가능합니다");
            destAirtkClssCd.focus();
            return false;
        }
    }
    if (frm.destReservprnTpCd.value !== "") {
        if (frm.destTpCd.value === "01") {
            await $c.win.alert("지방 출발시만  선택 가능합니다");
            destReservprnTpCd.focus();
            return false;
        }
    }
    if (frm.disclsEduEvtAddContn.value !== "") {
        if (frm.disclsEduEvtTpCd.value !== "1") {
            await $c.win.alert("골프 선택시만  작성 가능합니다");
            disclsEduEvtAddContn.focus();
            return false;
        }
    }
    return true;
};
